def choose_path(source, destination, b):
    # reserve's exact feasible-path and ranking semantics, in
    # polynomial time. A candidate edge e usable for this add has
    # residual >= b; using it after the add loads it to
    # f_e = (used+b)/C = (C-residual+b)/C, and a path's rank key is
    # the path's maximum f_e, then its cost sum, then its node
    # sequence. The maximum is a minimax ("widest path") label, so
    # stage 1 settles the smallest achievable fraction rho* at the
    # destination with integer cross multiplication (never floats).
    # Every minimax-optimal path is exactly an s->d path whose edges
    # all satisfy f_e <= rho*, so stage 2 runs the codebase's
    # O(V**2) lowest-cost Dijkstra (full-node-sequence Unicode tie
    # break) over that edge subgraph. The two-stage winner is
    # provably identical to enumerating every feasible simple path,
    # yet costs O(V**2 + A) instead of the factorial enumeration.
    # Returns None when no capacity-feasible up path exists (both
    # unreachable and no-capacity map to status 2).
    def feasible(index):
        return residual[index] >= b

    # Stage 1: minimax label-setting over feasible up edges.
    lab_num = {n: None for n in nodes}
    lab_den = {n: None for n in nodes}
    lab_num[source], lab_den[source] = 0, 1
    settled = set()
    while True:
        u = None
        for n in nodes:
            if n in settled or lab_num[n] is None:
                continue
            if u is None or lab_num[n] * lab_den[u] < lab_num[u] * lab_den[n]:
                u = n
        if u is None:
            break
        settled.add(u)
        un, ud = lab_num[u], lab_den[u]
        for to, _, index in adj[u]:
            if not feasible(index) or to in settled:
                continue
            en = capacity[index] - residual[index] + b
            ed = capacity[index]
            cn, cd = (un, ud) if un * ed > en * ud else (en, ed)
            if (lab_num[to] is None
                    or cn * lab_den[to] < lab_num[to] * cd):
                lab_num[to], lab_den[to] = cn, cd
    if lab_num[destination] is None:
        return None
    rn, rd = lab_num[destination], lab_den[destination]

    # Stage 2: lowest cost, then lexicographic path, over feasible
    # up edges whose post-add utilization is no worse than rho*.
